package wgmodern;
import java.util.*;import java.util.concurrent.CompletableFuture;import net.minecraft.data.CachedOutput;import static wgmodern.WGData.*;
public class MetallurgyData {
 static Object tag(String value){return map("tag","forge:"+value);}
 static Object ore(String value){return map("kind","ore","names",List.of("#forge:"+value),"elements",List.of());}
 public static void add(WGData d,CachedOutput c,List<CompletableFuture<?>> jobs,List<Object> research,List<Object> pages){
  var clusterPages=new ArrayList<Object>();var transPages=new ArrayList<Object>();clusterPages.add(text("METALLURGICPERFECTION_CLUSTERS.1"));transPages.add(text("METALLURGICPERFECTION_TRANSMUTATION.1"));
  for(String metal:Metallurgy.METALS){String id=metal+"_cluster",cluster="cluster_"+metal,trans="transmute_"+metal;
   for(String source:List.of("ores","clusters"))jobs.add(d.save(c,"data/witchinggadgets/recipes/metal_bonus/"+metal+"_"+source+".json",map("type","witchinggadgets:metal_bonus","metal",metal,"ingredient",tag(source+"/"+metal),"result",item("minecraft:iron_nugget"))));
   for(int overlay=0;overlay<3;overlay++){String suffix=overlay==0?"":overlay==1?"nether":"end";var model=map("parent","minecraft:item/generated","textures",map("layer0","witchinggadgets:items/cluster_metal","layer1","witchinggadgets:items/cluster_overlay"+suffix));if(overlay==0)model.put("overrides",List.of(map("predicate",map("witchinggadgets:cluster_type",1),"model","witchinggadgets:item/"+id+"_1"),map("predicate",map("witchinggadgets:cluster_type",2),"model","witchinggadgets:item/"+id+"_2")));jobs.add(d.save(c,"assets/witchinggadgets/models/item/"+id+(overlay==0?"":"_"+overlay)+".json",model));}
   jobs.add(d.save(c,"data/forge/tags/items/clusters/"+metal+".json",map("replace",false,"values",List.of("witchinggadgets:"+id))));
   jobs.add(d.save(c,"data/witchinggadgets/recipes/cluster_smelt/"+metal+".json",map("type","witchinggadgets:cluster_smelting","metal",metal,"ingredient",item("witchinggadgets:"+id))));
   jobs.add(d.save(c,"data/witchinggadgets/recipes/blast/"+metal+".json",map("type","witchinggadgets:blast_furnace","ingredient",tag("clusters/"+metal),"result",map("tag","forge:ingots/"+metal,"count",3),"bonus",tag("nuggets/"+metal),"duration",440)));
   jobs.add(d.save(c,"data/witchinggadgets/recipes/"+cluster+".json",map("type","witchinggadgets:metal_crucible","metal",metal,"transmutation",false,"research","witchinggadgets:METALLURGICPERFECTION_CLUSTERS","catalyst",tag("ores/"+metal),"result",map("item","witchinggadgets:"+id,"count",2),"aspects",map("metallum",2,"ordo",2))));
   jobs.add(d.save(c,"data/witchinggadgets/recipes/"+cluster+"_from_raw.json",map("type","witchinggadgets:metal_crucible","metal",metal,"transmutation",false,"research","witchinggadgets:METALLURGICPERFECTION_CLUSTERS","catalyst",tag("raw_materials/"+metal),"result",item("witchinggadgets:"+id),"aspects",map("metallum",1,"ordo",1))));
   jobs.add(d.save(c,"data/witchinggadgets/recipes/"+trans+".json",map("type","witchinggadgets:metal_crucible","metal",metal,"transmutation",true,"nugget_transmutation",true,"research","witchinggadgets:METALLURGICPERFECTION_TRANSMUTATION","catalyst",tag("nuggets/"+metal),"result",map("item","minecraft:iron_nugget","count",3),"aspects",map("metallum",2))));
   d.display.add(map("key","witchinggadgets:"+cluster,"class","modern","data",map("kind","crucible","research","witchinggadgets:METALLURGICPERFECTION_CLUSTERS","catalyst",ore("ores/"+metal),"output",stack("witchinggadgets:"+id),"aspects",map("metallum",1,"ordo",1))));
   d.display.add(map("key","witchinggadgets:"+trans,"class","modern","data",map("kind","crucible","research","witchinggadgets:METALLURGICPERFECTION_TRANSMUTATION","catalyst",ore("nuggets/"+metal),"output",ore("nuggets/"+metal),"aspects",map("metallum",2))));
   clusterPages.add(recipe("CRUCIBLE_CRAFTING",cluster));transPages.add(recipe("CRUCIBLE_CRAFTING",trans));
  }
  jobs.add(d.save(c,"data/witchinggadgets/recipes/pure_cinnabar.json",map("type","thaumcraft:crucible","research","witchinggadgets:PURECINNABAR","catalyst",tag("ores/cinnabar"),"result",map("item","thaumcraft:cinnabar_cluster","count",2),"aspects",map("metallum",2,"ordo",2))));
  jobs.add(d.save(c,"data/witchinggadgets/recipes/pure_cinnabar_from_raw.json",map("type","thaumcraft:crucible","research","witchinggadgets:PURECINNABAR","catalyst",tag("raw_materials/cinnabar"),"result",item("thaumcraft:cinnabar_cluster"),"aspects",map("metallum",1,"ordo",1))));
  d.display.add(map("key","witchinggadgets:pure_cinnabar","class","modern","data",map("kind","crucible","research","witchinggadgets:PURECINNABAR","catalyst",ore("ores/cinnabar"),"output",stack("thaumcraft:cinnabar_cluster"),"aspects",map("metallum",1,"ordo",1))));
  var cinnabar=research("PURECINNABAR","calculator",-6,-3,1,Map.of("metallum",5,"ordo",1,"venenum",1),List.of("PUREIRON"),map("isConcealed",true,"isSecondary",true),2);cinnabar.put("icon_item",map("item","thaumcraft:cinnabar_cluster","count",1));research.add(cinnabar);pages.add(map("key","witchinggadgets:PURECINNABAR","pages",List.of(text("PURECINNABAR.1"),recipe("CRUCIBLE_CRAFTING","pure_cinnabar"))));
  for(boolean trans:List.of(false,true)){String key="METALLURGICPERFECTION_"+(trans?"TRANSMUTATION":"CLUSTERS");var r=research(key,"calculator",trans?-3:-6,-1,1,Map.of("metallum",20,"ordo",10,trans?"permutatio":"vitreus",10),trans?List.of("TRANSIRON","TRANSGOLD"):List.of("PUREIRON","PUREGOLD","witchinggadgets:PURECINNABAR"),map("isConcealed",true,"isSecondary",true,"isSpecial",true),trans?transPages.size():clusterPages.size());r.remove("icon_item");r.put("icon_resource","witchinggadgets:textures/gui/research/icon_mp_"+(trans?"trans":"cluster")+".png");research.add(r);pages.add(map("key","witchinggadgets:"+key,"pages",trans?transPages:clusterPages));}
 }
}
